function cheapestDrop(grid: number[][]): number {
  const n = grid.length;
  const go = (r: number, c: number): number => {
    if (c < 0 || c >= n) return Infinity;
    if (r === n - 1) return grid[r][c];
    return grid[r][c] + Math.min(go(r + 1, c - 1), go(r + 1, c), go(r + 1, c + 1));
  };
  let best = Infinity;
  for (let c = 0; c < n; c++) best = Math.min(best, go(0, c));
  return best;
}

