function cheapestDrop(grid: number[][]): number {
  const n = grid.length;
  let prev = grid[0].slice();
  for (let r = 1; r < n; r++) {
    const cur = new Array(n);
    for (let c = 0; c < n; c++) {
      let m = prev[c];
      if (c > 0) m = Math.min(m, prev[c - 1]);
      if (c < n - 1) m = Math.min(m, prev[c + 1]);
      cur[c] = grid[r][c] + m;
    }
    prev = cur;
  }
  return Math.min(...prev);
}

